<?php $pageTitle='Sales History'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/header.php'; $branchId=current_branch_id(); $stmt=$pdo->prepare('SELECT s.*, u.name cashier FROM sales s LEFT JOIN users u ON u.id=s.user_id WHERE s.branch_id=? ORDER BY s.id DESC'); $stmt->execute([$branchId]); ?>
<div class="table-card"><h5>Sales History</h5><table class="table"><thead><tr><th>Invoice</th><th>Cashier</th><th>Total</th><th>Payment</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($stmt as $s): ?><tr><td><?= htmlspecialchars($s['invoice_no']) ?></td><td><?= htmlspecialchars($s['cashier'] ?? '') ?></td><td>₱<?= number_format($s['total_amount'],2) ?></td><td><?= htmlspecialchars($s['payment_method']) ?></td><td><?= htmlspecialchars($s['status']) ?></td><td><?= htmlspecialchars($s['created_at']) ?></td><td><a class="btn btn-sm btn-outline-primary" href="receipt.php?id=<?= $s['id'] ?>">Receipt</a></td></tr><?php endforeach; ?></tbody></table></div>
